/* @lc app=leetcode id=3709 lang=kotlin */ class ExamTracker(val ts: ArrayList<Int> = ArrayList(), val ps: ArrayList<Long> = arrayListOf(0L)) { fun record(time: Int, score: Int) { ts.add(time).let { ps.add(ps.last() + score) } } fun lb(a: List<Int>, v: Int): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] < v) m + 1 to hi else lo to m } }.last().first fun totalScore(startTime: Int, endTime: Int): Long = ps[lb(ts, endTime + 1)] - ps[lb(ts, startTime)] }